`src/lib.rs`:

```rust
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

pub struct WorkspaceState {
    pub value: u64,
}

pub async fn actor_body(
    path: PathBuf,
    workspace: Arc<Mutex<WorkspaceState>>,
    notify: Arc<tokio::sync::Notify>,
    last_error: Arc<Mutex<String>>,
) {
    let mut previous: Option<Vec<u8>> = None;
    loop {
        notify.notified().await;
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        let _ = &path;
        {
            let guard = workspace.lock().unwrap();
            let bytes = guard.value.to_le_bytes().to_vec();
            if previous.as_deref() != Some(bytes.as_slice()) {
                previous = Some(bytes);
            }
        }
        {
            let mut err = last_error.lock().unwrap();
            err.clear();
        }
        let _ = &previous;
    }
}

pub fn spawn_supervisor(
    path: PathBuf,
    workspace: Arc<Mutex<WorkspaceState>>,
    notify: Arc<tokio::sync::Notify>,
    last_error: Arc<Mutex<String>>,
) {
    tokio::spawn(async move {
        loop {
            let inner_path = path.clone();
            let inner_workspace = Arc::clone(&workspace);
            let inner_notify = Arc::clone(&notify);
            let inner_last = Arc::clone(&last_error);
            let handle = tokio::spawn(actor_body(
                inner_path,
                inner_workspace,
                inner_notify,
                inner_last,
            ));
            let _ = handle.await;
        }
    });
}
