```rust
use std::ops::Add;
use std::ops::Mul;

pub struct Vec2<T> {
    pub x: T,
    pub y: T,
}

macro_rules! implement {
    ($type:ident) => {
        impl Add for Vec2<$type> {
            type Output = Self;
            fn add(self, rhs: Self) -> Self::Output {
                Self::Output { x: self.x + rhs.x, y: self.y + rhs.y }
            }
        }

        impl Mul<Vec2<$type>> for $type {
            type Output = Vec2<$type>;
            fn mul(self, rhs: Vec2<$type>) -> Self::Output {
                Self::Output { x: self * rhs.x, y: self * rhs.y }
            }
        }
    }
}

implement!(i32);
implement!(u32);

pub fn main() {
    let a = Vec2 { x: 1, y: 2 };
    let b = Vec2 { x: 3, y: 4 };
    let res = 5 * (a + b);
}
```

Incorrect behavior when there are two or more `implement!` calls (`res` should be `Vec2<i32>` instead of `i32`):
