```rust
#[non_exhaustive]
enum Foo {
    A,
    B,
}

impl Foo {
    pub fn do_thing(self) {
        match self {
            // Fill match arms generates the below three
            // lines given an empty `match self {}`:
            Foo::A => todo!(),
            Foo::B => todo!(),
            _ => todo!(), // this one is unnecessary
        }
    }
}
```

